    dir_sizes = {}

    # Iterate over the lines
    for line in lines:
        line = line.strip()
        if line.startswith('$'):
            # Command
            if line.startswith('$ cd'):
                # Change directory
                dir_name = line.split(' ')[2]
                if dir_name == '/':
                    current_dir = '/'
                elif dir_name == '..':
                    current_dir = os.path.dirname(current_dir)
                else:
                    current_dir = os.path.join(current_dir, dir_name)
            elif line.startswith('$ ls'):
                # List files
                continue
        else:
            # File or directory
            parts = line.split(' ')
            if parts[0] == 'dir':
                # Directory
                dir_name = parts[1]
                dir_path = os.path.join(current_dir, dir_name)
                if dir_path not in dir_sizes:
                    dir_sizes[dir_path] = 0
            else:
                # File
                file_size = int(parts[0])
                dir_path = current_dir
                while dir_path != '/':
                    if dir_path not in dir_sizes:
                        dir_sizes[dir_path] = 0
                    dir_sizes[dir_path] += file_size
                    dir_path = os.path.dirname(dir_path)
                if '/' not in dir_sizes:
                    dir_sizes['/'] = 0
                dir_sizes['/'] += file_size

    # Calculate the total size of each directory
    for dir_path in dir_sizes:
        total_size = 0
        for file_path in dir_sizes:
            if file_path.startswith(dir_path):
                total_size += dir_sizes[file_path]
        dir_sizes[dir_path] = total_size

    # Print the total size of each directory
    for dir_path in dir_sizes:
        print(f'{dir_path}: {dir_sizes[dir_path]}')

